#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM${e}[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Pact operator setup: everything in ticket 01's "Needs the operator" list.
#
#   scripts/setup-operator.sh        (from the repo root)
#
# Production values are remembered in .env.operator (gitignored, mode 0600) so a
# re-run offers them back instead of asking again. Google client values also go
# into .env for local development. Needs: flyctl, gh, openssl, curl.

ENV_FILE="${ENV_FILE:-.env.operator}"
DOMAIN="pact.hrishisd.com"
REGION="ewr"
VOLUME="pact_data"

# run CMD... shows a command, then runs it (output visible).
run() {
  printf '  %s$ %s%s\n' "$DIM" "$*" "$RESET"
  "$@"
}

# app_name reads `app = "..."` from fly.toml.
app_name() { sed -n 's/^app = "\(.*\)"/\1/p' fly.toml; }

run_wizard() {

TOTAL_STAGES=15

banner "Pact: production setup (Fly, R2, Google sign-in, DNS, monitoring, practice restore)"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Tools and logins"
say "This wizard drives flyctl and gh for you. Both must be installed and logged in."
for tool in fly gh openssl curl; do
  if command -v "$tool" >/dev/null 2>&1; then
    printf '  %s✓%s %s\n' "$GREEN" "$RESET" "$tool"
  else
    warn "$tool is missing"
  fi
done
step "No flyctl? brew install flyctl   (then: fly auth login)"
step "No gh? brew install gh           (then: gh auth login)"
note "Run this from the repo root: it reads fly.toml and writes .env.operator and .env."
pause "Press Enter once 'fly auth whoami' and 'gh auth status' both work."
run fly auth whoami || warn "fly isn't logged in: run 'fly auth login', then re-run this wizard"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Fly app in $REGION"
say "fly.toml names the app '$(app_name)'. App names are global on Fly, so it may be taken."
run fly platform regions | grep -Ei "name|ewr|iad" || true
note "ADR 0002 wants ewr (fallback iad). If ewr isn't listed, set primary_region = \"iad\" in fly.toml and use iad below."
note "While you're here, check current pricing: https://fly.io/docs/about/pricing/ (expect ~\$3-5/month)."
ask FLY_APP "Fly app name (must match 'app' in fly.toml):"
write_env FLY_APP "$FLY_APP"
if [[ "$FLY_APP" != "$(app_name)" ]]; then
  warn "fly.toml says app = \"$(app_name)\". Edit it to \"$FLY_APP\" and commit, or deploys go to the wrong app."
  pause "Press Enter once fly.toml is updated."
fi
if fly status -a "$FLY_APP" >/dev/null 2>&1; then
  say "App $FLY_APP already exists. Skipping creation."
elif confirm "Create Fly app '$FLY_APP' now?"; then
  run fly apps create "$FLY_APP"
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Fly volume at /data"
say "One volume, '$VOLUME', in $REGION, mounted at /data (fly.toml [[mounts]])."
say "Fly takes daily volume snapshots by default; we keep 5 days as a backstop behind Litestream."
run fly volumes list -a "$FLY_APP" || true
if fly volumes list -a "$FLY_APP" 2>/dev/null | grep -q "$VOLUME"; then
  say "A '$VOLUME' volume already exists. Skipping."
elif confirm "Create a 1 GB volume '$VOLUME' in $REGION (snapshots kept 5 days)?"; then
  note "flyctl warns that a volume pins the app to one host: that's the accepted trade-off (ADR 0002). Answer yes."
  run fly volumes create "$VOLUME" --region "$REGION" --size 1 --snapshot-retention 5 -a "$FLY_APP"
fi

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: bucket for Litestream"
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2 Object Storage → Create bucket."
step "Name it e.g. pact-litestream. Location: Automatic, or a hint of Eastern North America. Storage class: Standard."
step "Leave public access OFF. (Photos get their own private bucket in stage 6.)"
ask LITESTREAM_BUCKET "Bucket name:"
write_env LITESTREAM_BUCKET "$LITESTREAM_BUCKET"
step "On the R2 overview page, copy your Account ID (right-hand side, 'Account Details')."
ask R2_ACCOUNT_ID "Cloudflare Account ID:"
write_env R2_ACCOUNT_ID "$R2_ACCOUNT_ID"
write_env LITESTREAM_ENDPOINT "https://${R2_ACCOUNT_ID}.r2.cloudflarestorage.com"

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: access keys for Litestream"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "R2 → Manage API tokens → Create Account API token (or User API token)."
step "Name: pact-litestream. Permissions: Object Read & Write."
step "Specify bucket(s): only '$LITESTREAM_BUCKET'. TTL: forever."
step "Create, then copy the S3 'Access Key ID' and 'Secret Access Key' (shown once)."
ask LITESTREAM_ACCESS_KEY_ID "Access Key ID:"
ask_secret LITESTREAM_SECRET_ACCESS_KEY "Secret Access Key (hidden):"
write_env LITESTREAM_ACCESS_KEY_ID "$LITESTREAM_ACCESS_KEY_ID"
write_env LITESTREAM_SECRET_ACCESS_KEY "$LITESTREAM_SECRET_ACCESS_KEY"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Cloudflare R2: private bucket and access keys for photos"
say "Evidence photos live in their own private bucket. Only the server reads it, and it"
say "shows a photo only to the pact's owner and reviewers. Development keeps photos on local disk."
open_url "https://dash.cloudflare.com/?to=/:account/r2/overview"
step "R2 Object Storage → Create bucket."
step "Name it e.g. pact-photos. Same location and storage class as '$LITESTREAM_BUCKET'."
step "Leave public access OFF: no public bucket URL, no custom domain."
ask PHOTOS_BUCKET "Bucket name:"
write_env PHOTOS_BUCKET "$PHOTOS_BUCKET"
write_env PHOTOS_ENDPOINT "https://${R2_ACCOUNT_ID}.r2.cloudflarestorage.com"
open_url "https://dash.cloudflare.com/?to=/:account/r2/api-tokens"
step "R2 → Manage API tokens → Create Account API token (or User API token)."
step "Name: pact-photos. Permissions: Object Read & Write."
step "Specify bucket(s): only '$PHOTOS_BUCKET'. TTL: forever."
step "Create, then copy the S3 'Access Key ID' and 'Secret Access Key' (shown once)."
ask PHOTOS_ACCESS_KEY_ID "Access Key ID:"
ask_secret PHOTOS_SECRET_ACCESS_KEY "Secret Access Key (hidden):"
write_env PHOTOS_ACCESS_KEY_ID "$PHOTOS_ACCESS_KEY_ID"
write_env PHOTOS_SECRET_ACCESS_KEY "$PHOTOS_SECRET_ACCESS_KEY"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in: consent screen"
open_url "https://console.cloud.google.com/auth/overview"
step "Pick or create a project (e.g. 'Pact')."
step "Get started / Branding: App name 'Pact', your email as support and developer contact."
step "Audience: External. Then 'Publish app' so it's In production."
note "Only the basic scopes (openid, email, profile) are used, so no Google verification is needed."
note "Left in Testing, only listed test users could sign in at all."
pause "Press Enter once the consent screen is set up."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Google sign-in: OAuth client"
open_url "https://console.cloud.google.com/auth/clients"
step "Create client → Application type: Web application → Name: Pact."
step "Authorized JavaScript origins:  https://$DOMAIN   and   http://localhost:5173"
step "Authorized redirect URIs:"
step "    https://$DOMAIN/api/auth/callback/google"
step "    http://localhost:5173/api/auth/callback/google"
step "Create, then copy the Client ID and Client secret."
ask GOOGLE_CLIENT_ID "Client ID:"
ask_secret GOOGLE_CLIENT_SECRET "Client secret (hidden):"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Operator email and session secret"
say "The operator email is the Google account whose first sign-in creates the first account."
say "Every other account will need an invite."
ask OPERATOR_EMAIL "Your Google account email:"
write_env OPERATOR_EMAIL "$OPERATOR_EMAIL"
if [[ -n "$(_existing BETTER_AUTH_SECRET || true)" ]]; then
  BETTER_AUTH_SECRET=$(_existing BETTER_AUTH_SECRET)
  say "Keeping the existing session secret (changing it would sign everyone out)."
else
  write_env BETTER_AUTH_SECRET "$(openssl rand -base64 32)"
  say "Generated a new session secret."
fi

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Local development .env"
say "npm run dev reads .env. It gets the same Google client, your email, and its own session secret."
OPERATOR_FILE="$ENV_FILE"
PROD_AUTH_SECRET="$BETTER_AUTH_SECRET"
ENV_FILE=".env"
write_env GOOGLE_CLIENT_ID "$GOOGLE_CLIENT_ID"
write_env GOOGLE_CLIENT_SECRET "$GOOGLE_CLIENT_SECRET"
write_env OPERATOR_EMAIL "$OPERATOR_EMAIL"
write_env BETTER_AUTH_URL "http://localhost:5173"
if [[ -z "$(_existing BETTER_AUTH_SECRET || true)" ]]; then
  write_env BETTER_AUTH_SECRET "$(openssl rand -base64 32)"
fi
ENV_FILE="$OPERATOR_FILE"
BETTER_AUTH_SECRET="$PROD_AUTH_SECRET"   # stage 11 sends the production one to Fly
pause

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Fly secrets"
say "These names are exactly what the server and litestream.yml read:"
for name in OPERATOR_EMAIL GOOGLE_CLIENT_ID GOOGLE_CLIENT_SECRET BETTER_AUTH_SECRET \
            LITESTREAM_BUCKET LITESTREAM_ENDPOINT LITESTREAM_ACCESS_KEY_ID LITESTREAM_SECRET_ACCESS_KEY \
            PHOTOS_BUCKET PHOTOS_ENDPOINT PHOTOS_ACCESS_KEY_ID PHOTOS_SECRET_ACCESS_KEY; do
  note "  $name"
done
note "NODE_ENV, PORT, PACT_DB_PATH and BETTER_AUTH_URL=https://$DOMAIN are in fly.toml [env], not secrets."
if confirm "Set these 12 secrets on '$FLY_APP' (staged: they apply on the next deploy)?"; then
  # Through stdin, so no secret shows up in the process list.
  printf '%s\n' \
    "OPERATOR_EMAIL=$OPERATOR_EMAIL" \
    "GOOGLE_CLIENT_ID=$GOOGLE_CLIENT_ID" \
    "GOOGLE_CLIENT_SECRET=$GOOGLE_CLIENT_SECRET" \
    "BETTER_AUTH_SECRET=$BETTER_AUTH_SECRET" \
    "LITESTREAM_BUCKET=$LITESTREAM_BUCKET" \
    "LITESTREAM_ENDPOINT=$LITESTREAM_ENDPOINT" \
    "LITESTREAM_ACCESS_KEY_ID=$LITESTREAM_ACCESS_KEY_ID" \
    "LITESTREAM_SECRET_ACCESS_KEY=$LITESTREAM_SECRET_ACCESS_KEY" \
    "PHOTOS_BUCKET=$PHOTOS_BUCKET" \
    "PHOTOS_ENDPOINT=$PHOTOS_ENDPOINT" \
    "PHOTOS_ACCESS_KEY_ID=$PHOTOS_ACCESS_KEY_ID" \
    "PHOTOS_SECRET_ACCESS_KEY=$PHOTOS_SECRET_ACCESS_KEY" \
    | if fly secrets import --stage -a "$FLY_APP"; then
        printf '  %s✓ set%s 12 Fly secrets on %s\n' "$GREEN" "$RESET" "$FLY_APP"
      else
        warn "fly secrets import failed: fix the error above and re-run this wizard"
      fi
  run fly secrets list -a "$FLY_APP"
else
  SKIPPED+=("Fly secrets on $FLY_APP")
fi

# ── 12 ────────────────────────────────────────────────────────────────────
stage "GitHub Actions: FLY_API_TOKEN, then first deploy"
say "CI deploys with a deploy token scoped to this one app (.github/workflows/ci.yml)."
if confirm "Create a Fly deploy token for '$FLY_APP' and store it as the GitHub secret FLY_API_TOKEN?"; then
  FLY_API_TOKEN=$(fly tokens create deploy -a "$FLY_APP" -x 87600h)
  set_secret FLY_API_TOKEN "$FLY_API_TOKEN"
else
  SKIPPED+=("GitHub secret FLY_API_TOKEN (fly tokens create deploy -a $FLY_APP | gh secret set FLY_API_TOKEN)")
fi
say "Now deploy: push to main and let CI run tests then 'flyctl deploy --remote-only',"
say "or deploy from here once to see it work."
if confirm "Run 'fly deploy --remote-only' from this machine now?"; then
  run fly deploy --remote-only -a "$FLY_APP"
fi
pause "Press Enter once a deploy has finished (fly status shows the machine started)."
run curl -fsS "https://$FLY_APP.fly.dev/health" || warn "/health didn't answer 200 yet: check 'fly logs -a $FLY_APP'"
printf '\n'
pause

# ── 13 ────────────────────────────────────────────────────────────────────
stage "DNS and certificate for $DOMAIN"
run fly certs add "$DOMAIN" -a "$FLY_APP" || true
say "flyctl just printed the DNS records it wants. The simplest is one CNAME:"
step "Name: pact   Type: CNAME   Target: $FLY_APP.fly.dev"
note "If hrishisd.com's DNS is on Cloudflare, set the record to 'DNS only' (grey cloud), or Fly can't issue the cert."
pause "Press Enter once the DNS record is saved at your DNS provider."
run fly certs check "$DOMAIN" -a "$FLY_APP" || true
note "Issuing can take a few minutes. Re-check with: fly certs check $DOMAIN -a $FLY_APP"
pause "Press Enter once the certificate shows as issued (or to come back to it later)."

# ── 14 ────────────────────────────────────────────────────────────────────
stage "Sign in on the iPhone, and an uptime monitor"
step "On your iPhone, open https://$DOMAIN in Safari → Share → Add to Home Screen."
step "Open Pact from the home screen, sign in with $OPERATOR_EMAIL, confirm the timezone, see Today."
step "Sign out, sign in with a different Google account: you should land on 'You need an invite'."
note "Record whether Google sign-in completed inside the home-screen app in the ticket's Comments (ADR 0002 'Still to verify')."
pause "Press Enter when done."
open_url "https://dashboard.uptimerobot.com/monitors"
step "Any free uptime monitor works; with UptimeRobot: New monitor → HTTP(s)."
step "URL: https://$DOMAIN/health   Interval: 5 minutes   Alert contact: your email."
note "/health turns 503 when the scheduler hasn't ticked for 5 minutes."
pause "Press Enter once the monitor is created and shows Up."

# ── 15 ────────────────────────────────────────────────────────────────────
stage "Practice restore (ADR 0002): delete the volume, redeploy, read the alert"
say "Do this now, before real data depends on backups. It throws away the volume."
step "First, check Litestream is replicating: 'fly logs -a $FLY_APP' shows litestream lines with no errors,"
step "and the R2 bucket '$LITESTREAM_BUCKET' has objects under pact.db/."
step "Note the time now: the restored database's last tick should be within a minute or two of it."
if confirm "Destroy the machine and the '$VOLUME' volume, create a fresh volume, and redeploy?"; then
  run fly machine list -a "$FLY_APP"
  ask MACHINE_ID "Machine ID to destroy:"
  run fly machine destroy "$MACHINE_ID" --force -a "$FLY_APP"
  run fly volumes list -a "$FLY_APP"
  ask VOLUME_ID "Volume ID to destroy (vol_...):"
  run fly volumes destroy "$VOLUME_ID" --yes -a "$FLY_APP"
  run fly volumes create "$VOLUME" --region "$REGION" --size 1 --snapshot-retention 5 --yes -a "$FLY_APP"
  run fly deploy --remote-only -a "$FLY_APP"
  say "Now look for two lines in the boot log:"
  step "'litestream restored /data/pact.db from the replica'"
  step "'OPERATOR_ALERT database restored from backup; last scheduler tick before the restore: <time>'"
  run fly logs -a "$FLY_APP" --no-tail | grep -E "litestream restored|OPERATOR_ALERT" || \
    warn "not in the recent logs yet: run 'fly logs -a $FLY_APP' and look for them"
  step "Then sign in on the iPhone again: your account and timezone should still be there."
  note "Record the result (and the tick time vs. when you started) in the ticket's Comments."
  pause
else
  SKIPPED+=("Practice restore (ADR 0002): delete the volume, redeploy, check the OPERATOR_ALERT line")
fi

finish
}

run_wizard "$@"; exit
